"""Regenerate synthetic gesture stress fixtures. No owner/device traces are represented here."""
from pathlib import Path
import math

HERE = Path(__file__).resolve().parent
# One 32-point Z sample captured by s_shape_1_record through the real recording UI.
Z = ('00001c00370053006e008a00a600c100dd00f802ed12d926c639b24d9f608b747887'
     '649b51ae3dc22ad516e907fb22ff3eff59ff75ff91ffacffc8ffe3ffffff')

def encode(vertices):
    lengths = [0.0]
    for a, b in zip(vertices, vertices[1:]):
        lengths.append(lengths[-1] + math.dist(a, b))
    points = []
    for i in range(32):
        target = lengths[-1] * i / 31
        j = next((j for j in range(1, len(lengths)) if lengths[j] >= target), len(lengths)-1)
        f = (target-lengths[j-1]) / max(1e-9, lengths[j]-lengths[j-1])
        a, b = vertices[j-1], vertices[j]
        points.extend(round(a[k]+f*(b[k]-a[k])) for k in range(2))
    return bytes(max(0, min(255, v)) for v in points).hex()

def shape_line(action, sample):
    assert len(sample) == 128
    return f'shape.{action}=1,2,{sample},{sample}\n'

ACTIONS = ['undo','redo','previous-page','next-page','previous-tool','next-tool','white',
           'index','eraser-mode','clear-page','first-page','last-page','new-page','fit-page',
           'pages','tool-picker','paper','display','pen-feel','fold-panel','library',
           'close-menu','add-link','name-page','status-toggle','links','go-to-page','go-back',
           'link-areas','landscape-fit','shape-hold','status-corner']
for count, name in [(32, 'match32'), (8, 'stress8')]:
    folder = HERE / name
    folder.mkdir(exist_ok=True)
    text = '# Synthetic matching stress set; generated by ../generate.py.\n' + shape_line('undo', Z)
    for i, action in enumerate(ACTIONS[1:count], 1):
        # Closed loops of differing aspect/phase, deliberately far from the open Z target.
        points = [(round(127+120*math.cos(t*math.tau/64)),
                   round(127+(78+i%42)*math.sin(t*math.tau/64))) for t in range(65)]
        text += shape_line(action, encode(points))
    (folder/'gestures.ini').write_text(text)

# The fingershape_synth "drift" algorithm: wandering heading, bounded bend, forty steps.
# This Python port uses sin/cos rather than the Rust integer table. It is synthetic coverage,
# not an owner capture, not the missing owner J/K acceptance evidence.
for seed in range(1, 5):
    state = (seed*2654435761+0x9e3779b9) & 0xffffffff | 1
    def rnd(lo, hi):
        global state
        state ^= state << 13 & 0xffffffff
        state ^= state >> 17
        state ^= state << 5 & 0xffffffff
        state &= 0xffffffff
        return lo + state % (hi-lo+1)
    heading, bend = rnd(0,359)*16, rnd(-48,48)
    x, y = 950, 1150
    lines = ['# SYNTHETIC palm drift; see generate.py. Owner J/K traces unavailable.',
             '# grimoire touch-trace 1, rotation 0, 1860x2480, dpi 300',
             'P 1000 leave', f'F 2500 0:1:{x}:{y}:0:0']
    for i in range(1,41):
        bend = max(-96, min(96, bend+rnd(-16,16)))
        heading += bend
        x += round(12*math.cos(math.radians(heading/16)))
        y += round(12*math.sin(math.radians(heading/16)))
        lines.append(f'F {2500+i*20} 0:1:{x}:{y}:0:0')
    lines.append('F 3320')
    (HERE/f'synthetic-drift-{seed}.txt').write_text('\n'.join(lines)+'\n')
